#include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>

using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

ll sum_modulo(ll x, ll y) {
    return (x + y) % MOD;
}

ll diff_modulo(ll x, ll y) {
    x -= y;
    return (x < 0) ? x + MOD : x;
}

ll mult_modulo(ll x, ll y) {
    return (x * y) % MOD;
}

ll pow_modulo(ll base, ll exp) {
    if (exp == 0) return 1;
    if (exp & 1) return mult_modulo(base, pow_modulo(base, exp - 1));
    return pow_modulo(mult_modulo(base, base), exp >> 1);
}

ll inv_modulo(ll x) {
    return pow_modulo(x, MOD - 2);
}

int n_var;
vector<vector<ll>> A_var;
ll T_var[8][1 << 7][1 << 7];
unordered_map<ll,ll> DP_var;
vector<int> family_count_var(1 << 7, 0);
vector<int> family_id_var(1 << 7, 0);
vector<vector<int>> family_mask_list_var;

void setup() {
    family_mask_list_var.resize(n_var + 1);
    for (int mask=1; mask<(1<<n_var); ++mask) {
        family_count_var[mask] = family_count_var[mask>>1] + (mask & 1);
    }
    for (int mask=0; mask<(1<<n_var); ++mask) {
        family_id_var[mask] = (int)family_mask_list_var[family_count_var[mask]].size();
        family_mask_list_var[family_count_var[mask]].push_back(mask);
    }
    for (int k=0; k<=n_var; ++k) {
        for (int i=0; i<(int)family_mask_list_var[k].size(); ++i) {
            int cm=family_mask_list_var[k][i];
            for (int mask=0; mask<(1<<n_var); ++mask) {
                ll ans=0;
                if ((mask & cm)==mask) continue;
                for (int x=0; x<n_var; ++x) {
                    if (cm & (1<<x)) continue;
                    if ((mask & (1<<x))==0) continue;
                    int newmask=cm | (1<<x);
                    ans |= (1ll << family_id_var[newmask]);
                }
                T_var[k][i][mask]=ans;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin>>n_var;
    A_var.resize(n_var);
    for (int i=0; i<n_var; ++i) {
        A_var[i].resize(n_var);
        for (int j=0; j<n_var; ++j) {
            cin>>A_var[i][j];
            A_var[i][j]=mult_modulo(A_var[i][j],inv_modulo(100));
        }
    }
    setup();
    for (auto &entry:DP_var) entry.second=0;
    DP_var[1]=1;
    for (int k=0; k<n_var; ++k) {
        unordered_map<ll,ll> newDP;
        for (auto &S:DP_var) {
            ll mask=S.first;
            ll p=S.second;
            ll prob=1;
            for (int i=0; i<n_var; ++i) {
                if (mask & (1<<i))
                    prob=mult_modulo(prob,A_var[k][i]);
                else
                    prob=mult_modulo(prob,diff_modulo(1,A_var[k][i]));
            }
            for (int edges=0; edges<(1<<n_var); ++edges) {
                ll new_mask=0;
                ll p2=mult_modulo(prob, p);
                for (int i=0; i<(int)family_mask_list_var[k].size(); ++i) {
                    if (mask & (1<<i))
                        new_mask |= T_var[k][i][edges];
                }
                if (new_mask != 0)
                    newDP[new_mask]=sum_modulo(newDP[new_mask],p2);
            }
        }
        DP_var = move(newDP);
    }
    cout<<DP_var[1]<<endl;
    return 0;
}
